func OilWordNext(c *port.Cells, at int32, word int32) int32 {
	var text int32 = OilWordText(c, at, word)
	var count int32 = port.CellsAt(c, text-1)
	var p int32 = (text + 1) + port.CellsAt(c, text)
	var i int32 = 0
	for i < count {
		p = OilSymNext(c, p)
		i += 1
	}
	return p
}

func oilInsert(c *port.Cells, p int32, value int32) int32 {
	var i int32 = port.CellsLen(c)
	port.CellsPush(c, 0)
	for i > p {
		port.CellsSet(c, i, port.CellsAt(c, i-1))
		i -= 1
	}
	port.CellsSet(c, p, value)
	return 0
}

func OilWalt(c *port.Cells, at int32, word int32, conf int32) int32 {
	// Append alternatives before symbols and before starting the next word; insertion shifts later cells.
	var caps int32 = OilGet(c, at, OhCaps())
	if OilHas(caps, OcWalts()) == 0 {
		return -1
	}
	var count int32 = (word + OilWordBase(caps)) + -1
	var p int32 = OilWordText(c, at, word) - 1
	oilInsert(c, p, conf)
	oilInsert(c, p+1, 0)
	port.CellsSet(c, count, port.CellsAt(c, count)+1)
	return p
}

func OilWaltCp(c *port.Cells, alt int32, cp int32) int32 {
	var n int32 = port.CellsAt(c, alt+1)
	oilInsert(c, (alt+2)+n, cp)
	port.CellsSet(c, alt+1, n+1)
	return 0
}

func OilLineField(c *port.Cells, at int32, index int32, field int32) int32 {
	var caps int32 = OilGet(c, at, OhCaps())
	var row int32 = OilLineAt(c, at, index)
	var p int32 = row + 6
	if field < 4 {
		return port.CellsAt(c, row+field)
	}
	if field == 8 {
		if OilHas(caps, OcBlocks()) == 0 {
			return index
		}
		return port.CellsAt(c, row+4)
	}
	if field == 10 {
		if OilHas(caps, OcBtype()) == 0 {
			return 0
		}
		var block int32 = port.CellsAt(c, row+4)
		if block < 0 {
			return 0
		}
		var b int32 = OilBlockAt(c, at, block)
		return port.CellsAt(c, (b+5)+(3*OilHas(caps, OcWdir())))
	}
	p += OilHas(caps, OcLconf())
	if field == 9 {
		if OilHas(caps, OcParas()) == 0 {
			return index
		}
		return port.CellsAt(c, p)
	}
	p += OilHas(caps, OcParas())
	if (field >= 4) && (field <= 7) {
		if OilHas(caps, OcBaseline()) == 0 {
			return -1
		}
		return port.CellsAt(c, p+(field-4))
	}
	p += 4 * OilHas(caps, OcBaseline())
	if (field >= 11) && (field <= 13) {
		if OilHas(caps, OcRowmetrics()) == 0 {
			return -1
		}
		return port.CellsAt(c, p+(field-11))
	}
	return -1
}

func OilHeaderField(c *port.Cells, at int32, field int32, capability int32, fallback int32) int32 {
	if OilHas(OilGet(c, at, OhCaps()), capability) == 0 {
		return fallback
	}
	return OilGet(c, at, field)
}

func OilWordField(c *port.Cells, at int32, word int32, capability int32, fallback int32) int32 {
	var caps int32 = OilGet(c, at, OhCaps())
	var p int32 = word + 6
	if OilHas(caps, capability) == 0 {
		return fallback
	}
	if capability == OcWlang() {
		return port.CellsAt(c, p)
	}
	p += OilHas(caps, OcWlang())
	if capability == OcStyle() {
		return port.CellsAt(c, p)
	}
	p += OilHas(caps, OcStyle())
	if capability == OcPsize() {
		return port.CellsAt(c, p)
	}
	p += OilHas(caps, OcPsize())
	return port.CellsAt(c, p)
}

func OilFind(c *port.Cells, at int32) int32 {
	if at < 0 {
		return -1
	}
	if port.CellsAt(c, at) < 28 {
		return -1
	}
	if OilGet(c, at, 0) != OilVersion() {
		return -1
	}
	return at
}

