func OilBlockField(c *port.Cells, at int32, index int32, field int32) int32 {
	if OilHas(OilGet(c, at, OhCaps()), OcWdir()) == 0 {
		return 0
	}
	var p int32 = OilBlockAt(c, at, index)
	return port.CellsAt(c, (p+5)+field)
}

func OilWordFlags(c *port.Cells, at int32, word int32) int32 {
	// Evidence dictionary and numeric bits. Numeric is derived from text, not an engine claim.
	var n int32 = OilWlen(c, at, word)
	var i int32 = 0
	var digits int32 = 0
	var other int32 = 0
	var flags int32 = 0
	if (OilWlex(c, at, word) & 2) != 0 {
		flags = 1
	}
	for i < n {
		var cp int32 = OilWcp(c, at, word, i)
		if (cp >= 48) && (cp <= 57) {
			digits += 1
		} else if (cp != 46) && ((cp != 44) && ((cp != 45) && (cp != 43))) {
			other = 1
		}
		i += 1
	}
	if (digits > 0) && (other == 0) {
		flags += 2
	}
	return flags
}

func OilSegFromTess(psm int32) int32 {
	if psm == 6 {
		return SgBlock()
	}
	if psm == 7 {
		return SgSingleLine()
	}
	if psm == 11 {
		return SgSparse()
	}
	if psm == 8 {
		return SgSingleWord()
	}
	return SgPageAuto()
}

func OilTessBegin(c *port.Cells, id int32, psm int32, symbols int32, orient int32, wdir int32, order int32, deskew int32, osd int32, script int32, sconf int32, oconf int32, binary int32) int32 {
	var caps int32 = 2225423
	var at int32 = 0
	if symbols != 0 {
		caps += 917504
	}
	if osd >= 0 {
		caps += 2560
	}
	if binary != 0 {
		caps += OcBinary()
	}
	at = OilBegin(c, id, OenTesseract(), caps, caps, OilSegFromTess(psm), OilCkWord(), 0, LgLayout())
	OilSet(c, at, OhOrient(), osd/90)
	OilSet(c, at, OhOconf(), oconf)
	OilSet(c, at, OhDeskew(), deskew)
	OilSet(c, at, OhScript(), script)
	OilSet(c, at, OhSconf(), sconf)
	OilSet(c, at, OhWdir(), wdir)
	OilSet(c, at, OhLorder(), order)
	OilSet(c, at, OhBinary(), binary)
	return at
}

func oilFlatWordEnd(v *port.Cells, p int32, caps int32) int32 {
	var n int32 = port.CellsLen(v)
	var q int32 = p + 6
	var i int32 = 0
	var j int32 = 0
	var count int32 = 0
	var alts int32 = 0
	q = (((q + OilHas(caps, OcWlang())) + OilHas(caps, OcStyle())) + OilHas(caps, OcPsize())) + OilHas(caps, OcLexicon())
	if OilHas(caps, OcWalts()) != 0 {
		if q >= n {
			return -1
		}
		count = port.CellsAt(v, q)
		q += 1
		if count < 0 {
			return -1
		}
		for i < count {
			if (q + 1) >= n {
				return -1
			}
			if port.CellsAt(v, q+1) < 0 {
				return -1
			}
			if port.CellsAt(v, q+1) > ((n - q) - 2) {
				return -1
			}
			q = (q + 2) + port.CellsAt(v, q+1)
			if q > n {
				return -1
			}
			i += 1
		}
	}
	if (q + 1) >= n {
		return -1
	}
	count = port.CellsAt(v, q)
	if count < 0 {
		return -1
	}
	if (OilHas(caps, OcSymbols()) == 0) && (count != 0) {
		return -1
	}
	if port.CellsAt(v, q+1) < 0 {
		return -1
	}
	if port.CellsAt(v, q+1) > ((n - q) - 2) {
		return -1
	}
	q = (q + 2) + port.CellsAt(v, q+1)
	i = 0
	for i < count {
		if (q + 6) >= n {
			return -1
		}
		if port.CellsAt(v, q+5) < 0 {
			return -1
		}
		if port.CellsAt(v, q+5) > ((n - q) - 7) {
			return -1
		}
		alts = port.CellsAt(v, q+6)
		if alts < 0 {
			return -1
		}
		if (OilHas(caps, OcAlts()) == 0) && (alts != 0) {
			return -1
		}
		q = (q + 7) + port.CellsAt(v, q+5)
		j = 0
		for j < alts {
			if (q + 1) >= n {
				return -1
			}
			if port.CellsAt(v, q) < 0 {
				return -1
			}
			if port.CellsAt(v, q) > ((n - q) - 2) {
				return -1
			}
			q = (q + 2) + port.CellsAt(v, q)
			if q > n {
				return -1
			}
			j += 1
		}
		i += 1
	}
	if q > n {
		return -1
	}
	return q
}

func OilFlat(v *port.Cells, id int32, out *port.Cells) int32 {
	// Flat OIL is the header and rows without the four-cell answer envelope. Validate before writing.
	var n int32 = port.CellsLen(v)
	var p int32 = 24
	var i int32 = 0
	var caps int32 = 0
	var nb int32 = 0
	var nl int32 = 0
	var nw int32 = 0
	if n < 24 {
		return -1
	}
	if port.CellsAt(v, 0) != OilVersion() {
		return -1
	}
	if (port.CellsAt(v, 1) < 1) || (port.CellsAt(v, 1) > 5) {
		return -1
	}
	if (port.CellsAt(v, 7) < 0) || (port.CellsAt(v, 7) > 3) {
		return -1
	}
	if port.CellsAt(v, 21) < 0 {
		return -1
	}
	caps = port.CellsAt(v, 4)
	if (caps < 0) || (caps > 8388607) {
		return -1
	}
	if OilNativeCheck(caps, port.CellsAt(v, 5)) == 0 {
		return -1
	}
	nb = port.CellsAt(v, 18)
	nl = port.CellsAt(v, 19)
	nw = port.CellsAt(v, 20)
	if (nb < 0) || ((nl < 0) || (nw < 0)) {
		return -1
	}
	if (nb > n) || ((nl > n) || (nw > n)) {
		return -1
	}
	if (OilHas(caps, OcBlocks()) == 0) && (nb != 0) {
		return -1
	}
	p = (p + (nb * OilBlockStride(caps))) + (nl * OilLineStride(caps))
	if p > n {
		return -1
	}
	for i < nw {
		p = oilFlatWordEnd(v, p, caps)
		if p < 0 {
			return -1
		}
		i += 1
	}
	i = 0
	for i < port.CellsAt(v, 21) {
		if (p + 5) >= n {
			return -1
		}
		if port.CellsAt(v, p) < 6 {
			return -1
		}
		if port.CellsAt(v, p) > (n - p) {
			return -1
		}
		p += port.CellsAt(v, p)
		if p > n {
			return -1
		}
		i += 1
	}
	if p != n {
		return -1
	}
	port.CellsPush(out, n+4)
	port.CellsPush(out, 3)
	port.CellsPush(out, id)
	port.CellsPush(out, 0)
	i = 0
	for i < n {
		port.CellsPush(out, port.CellsAt(v, i))
		i += 1
	}
	return 0
}

func OilPolicyConf(c *port.Cells, at int32, word int32) int32 {
	return ocalib.OcalWord(OilGet(c, at, OhEngine()), 0, port.CellsAt(c, word+5))
}
